CREATE TYPE "OpsServiceStatus" AS ENUM ('OPERATIONAL','DEGRADED','MAINTENANCE','OUTAGE','RETIRED');
CREATE TYPE "OpsIncidentSeverity" AS ENUM ('SEV1','SEV2','SEV3','SEV4');
CREATE TYPE "OpsIncidentStatus" AS ENUM ('OPEN','INVESTIGATING','MITIGATING','RESOLVED','CLOSED');
CREATE TYPE "OpsDeploymentStatus" AS ENUM ('PLANNED','RUNNING','SUCCEEDED','FAILED','ROLLED_BACK','CANCELLED');
CREATE TABLE "OpsService" ("id" TEXT NOT NULL,"serviceKey" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"owner" TEXT,"status" "OpsServiceStatus" NOT NULL DEFAULT 'OPERATIONAL',"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "OpsService_pkey" PRIMARY KEY ("id"));
CREATE TABLE "OpsIncident" ("id" TEXT NOT NULL,"serviceId" TEXT,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"severity" "OpsIncidentSeverity" NOT NULL,"status" "OpsIncidentStatus" NOT NULL DEFAULT 'OPEN',"commander" TEXT,"resolution" TEXT,"resolvedAt" TIMESTAMP(3),"closedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "OpsIncident_pkey" PRIMARY KEY ("id"));
CREATE TABLE "OpsRunbook" ("id" TEXT NOT NULL,"runbookKey" TEXT NOT NULL,"serviceId" TEXT,"title" TEXT NOT NULL,"content" TEXT NOT NULL,"owner" TEXT,"version" INTEGER NOT NULL DEFAULT 1,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "OpsRunbook_pkey" PRIMARY KEY ("id"));
CREATE TABLE "OpsSla" ("id" TEXT NOT NULL,"serviceId" TEXT NOT NULL,"name" TEXT NOT NULL,"targetAvailability" INTEGER NOT NULL,"responseMinutes" INTEGER NOT NULL,"resolutionMinutes" INTEGER NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "OpsSla_pkey" PRIMARY KEY ("id"));
CREATE TABLE "OpsDeployment" ("id" TEXT NOT NULL,"serviceId" TEXT NOT NULL,"version" TEXT NOT NULL,"environment" TEXT NOT NULL DEFAULT 'production',"status" "OpsDeploymentStatus" NOT NULL DEFAULT 'PLANNED',"initiatedBy" TEXT,"notes" TEXT,"startedAt" TIMESTAMP(3),"completedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "OpsDeployment_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "OpsService_serviceKey_key" ON "OpsService"("serviceKey");
CREATE INDEX "OpsService_status_idx" ON "OpsService"("status");
CREATE INDEX "OpsIncident_serviceId_idx" ON "OpsIncident"("serviceId");
CREATE INDEX "OpsIncident_severity_status_idx" ON "OpsIncident"("severity","status");
CREATE INDEX "OpsIncident_createdAt_idx" ON "OpsIncident"("createdAt");
CREATE UNIQUE INDEX "OpsRunbook_runbookKey_key" ON "OpsRunbook"("runbookKey");
CREATE INDEX "OpsRunbook_serviceId_active_idx" ON "OpsRunbook"("serviceId","active");
CREATE UNIQUE INDEX "OpsSla_serviceId_key" ON "OpsSla"("serviceId");
CREATE INDEX "OpsDeployment_serviceId_status_idx" ON "OpsDeployment"("serviceId","status");
CREATE INDEX "OpsDeployment_createdAt_idx" ON "OpsDeployment"("createdAt");
ALTER TABLE "OpsIncident" ADD CONSTRAINT "OpsIncident_serviceId_fkey" FOREIGN KEY ("serviceId") REFERENCES "OpsService"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "OpsRunbook" ADD CONSTRAINT "OpsRunbook_serviceId_fkey" FOREIGN KEY ("serviceId") REFERENCES "OpsService"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "OpsSla" ADD CONSTRAINT "OpsSla_serviceId_fkey" FOREIGN KEY ("serviceId") REFERENCES "OpsService"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "OpsDeployment" ADD CONSTRAINT "OpsDeployment_serviceId_fkey" FOREIGN KEY ("serviceId") REFERENCES "OpsService"("id") ON DELETE CASCADE ON UPDATE CASCADE;
